/** The curriculum: which subjects a grade studies in a year, and how they are marked. */
export const gradeSubjects = defineTable(
  'grade_subjects',
  { module: 'M11', scope: 'org', member: 'read' },
  {
    ...baseColumns,
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    gradeId: uuid()
      .references((): AnyPgColumn => grades.id)
      .notNull(),
    subjectId: uuid()
      .references((): AnyPgColumn => subjects.id)
      .notNull(),
    /** set when only one stream takes it */
    subjectGroupId: uuid().references((): AnyPgColumn => subjectGroups.id),
    isCompulsory: boolean().notNull().default(true),
    periodsPerWeek: integer().notNull(),
    theoryMarks: decimal(6, 2).notNull(),
    practicalMarks: decimal(6, 2).notNull().default(0),
    /** overrides the grading scheme */
    passPercent: decimal(5, 2),
    countsInResult: boolean().notNull().default(true),
    bookTitle: text(),
    sortOrder: integer().notNull().default(0),
  },
  (t) => [
    nonNegative('grade_subjects', t.periodsPerWeek),
    nonNegative('grade_subjects', t.theoryMarks),
    nonNegative('grade_subjects', t.practicalMarks),
    between('grade_subjects', t.passPercent, 0, 100),
    uniqueIndex('grade_subjects_academic_year_grade_subject_subject_group_uq')
      .on(
        t.academicYearId,
        t.gradeId,
        t.subjectId,
        sql`coalesce(${t.subjectGroupId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);

